<?php
declare(strict_types=1);namespace App\Application\Underwriting;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter,Shared\CanonicalJson};use App\Models\{DisclosureSchemaVersion,Document,Proposal,ProposalDisclosureResponse,ProposalDocument,QuoteOffer,Tenant,UnderwritingCase,UnderwritingReferralTask,User};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
final class ProposalService{public function __construct(private CanonicalJson$json,private DocumentRequirementService$requirements,private AuditWriter$audit,private OutboxWriter$outbox){}public function create(Tenant$t,QuoteOffer$o,array$d,User$actor):Proposal{return DB::transaction(function()use($t,$o,$d,$actor){$o->load('quote');if($o->quote->tenant_id!==$t->id||$o->status!=='ACCEPTED')throw ValidationException::withMessages(['quote_offer_id'=>__('wave3.accepted_offer_required')]);if($o->quote->party_id!==$d['party_id'])throw ValidationException::withMessages(['party_id'=>__('wave3.party_mismatch')]);if(Proposal::where('quote_offer_id',$o->id)->where('status','!=','WITHDRAWN')->exists())throw ValidationException::withMessages(['quote_offer_id'=>__('wave3.proposal_exists')]);$schema=DisclosureSchemaVersion::whereHas('line',fn($q)=>$q->where('code',$o->quote->line_code))->where('status','APPROVED')->whereDate('effective_from','<=',now())->where(fn($q)=>$q->whereNull('effective_until')->orWhereDate('effective_until','>=',now()))->latest('version')->first();if(!$schema)throw ValidationException::withMessages(['disclosures'=>__('wave3.disclosure_schema_required')]);$p=Proposal::create(['tenant_id'=>$t->id,'quote_offer_id'=>$o->id,'party_id'=>$d['party_id'],'proposal_number'=>'PRP-'.now()->format('Ym').'-'.strtoupper(Str::random(8)),'status'=>'DISCLOSURES_PENDING','disclosures'=>[],'terms_snapshot'=>['offer_id'=>$o->id,'premium_minor'=>$o->premium_minor,'tax_minor'=>$o->tax_minor,'fee_minor'=>$o->fee_minor,'total_minor'=>$o->total_minor,'currency'=>$o->currency,'tariff_version_id'=>$o->tariff_version_id,'coverage_snapshot'=>$o->coverage_snapshot],'version'=>1,'disclosure_schema_version_id'=>$schema->id,'created_by'=>$actor->id]);$this->history($p,null,'DISCLOSURES_PENDING','CREATED',$actor);$this->audit->record('proposal.created','proposal',$p->id,['proposal_number'=>$p->proposal_number]);$this->outbox->record('proposal.created','proposal',$p->id,['proposal_id'=>$p->id]);return$p;});}public function answer(Proposal$p,array$answers,User$actor):Proposal{return DB::transaction(function()use($p,$answers,$actor){if(!in_array($p->status,['DISCLOSURES_PENDING','DRAFT'],true))throw ValidationException::withMessages(['status'=>__('wave3.disclosures_locked')]);$schema=$p->disclosureSchema;foreach($schema->questions as$q)if(($q['required']??false)&&!array_key_exists($q['code'],$answers))throw ValidationException::withMessages(["answers.{$q['code']}"=>__('wave3.answer_required')]);$flags=[];foreach($schema->questions as$q)if(in_array($answers[$q['code']]??null,$q['referral_values']??[],true))$flags[]=$q['referral_code']??$q['code'];ProposalDisclosureResponse::updateOrCreate(['proposal_id'=>$p->id,'disclosure_schema_version_id'=>$schema->id],['answers'=>$answers,'referral_flags'=>$flags,'answers_hash'=>$this->json->hash($answers)]);$p->update(['disclosures'=>$answers,'status'=>'DOCUMENTS_PENDING','version'=>$p->version+1]);$this->history($p,'DISCLOSURES_PENDING','DOCUMENTS_PENDING','DISCLOSURES_COMPLETED',$actor,['referral_flags'=>$flags]);return$p->refresh();});}public function attest(Proposal$p,User$actor):Proposal{$r=$p->disclosureResponse;if(!$r)throw ValidationException::withMessages(['answers'=>__('wave3.disclosures_required')]);if($this->json->hash($r->answers)!==$r->answers_hash)throw ValidationException::withMessages(['answers'=>__('wave3.answers_hash_mismatch')]);$r->update(['attested_at'=>now(),'attested_by'=>$actor->id]);$p->update(['attested_at'=>now()]);$this->audit->record('proposal.disclosures.attested','proposal',$p->id,['schema_id'=>$r->disclosure_schema_version_id]);return$p->refresh();}public function attachDocument(Proposal$p,Document$d,string$requirementCode):ProposalDocument{if($d->tenant_id!==$p->tenant_id||$d->party_id!==$p->party_id)throw ValidationException::withMessages(['document_id'=>__('wave3.document_ownership')]);$req=$this->requirements->applicable($p->offer->quote->line_code,$p->offer->quote->risk_facts)->firstWhere('code',$requirementCode);if(!$req)throw ValidationException::withMessages(['requirement_code'=>__('wave3.requirement_invalid')]);return ProposalDocument::updateOrCreate(['proposal_id'=>$p->id,'document_id'=>$d->id],['requirement_code'=>$req->code,'document_requirement_version_id'=>$req->id,'status'=>'SUBMITTED']);}public function verifyDocument(Proposal$p,Document$d,string$decision,string$notes,User$actor):ProposalDocument{$link=ProposalDocument::where(['proposal_id'=>$p->id,'document_id'=>$d->id])->firstOrFail();if($d->scan_status!=='CLEAN'&&$decision==='VERIFIED')throw ValidationException::withMessages(['status'=>__('wave3.clean_document_required')]);$link->update(['status'=>$decision,'verified_by'=>$actor->id,'verified_at'=>now(),'review_notes'=>$notes]);$this->audit->record('proposal.document.reviewed','document',$d->id,['proposal_id'=>$p->id,'decision'=>$decision]);return$link->refresh();}public function submit(Proposal$p,User$actor):Proposal{return DB::transaction(function()use($p,$actor){if($p->status!=='DOCUMENTS_PENDING'||!$p->attested_at)throw ValidationException::withMessages(['status'=>__('wave3.proposal_not_submittable')]);$required=$this->requirements->applicable($p->offer->quote->line_code,$p->offer->quote->risk_facts)->where('mandatory',true);foreach($required as$r)if(!$p->documents()->where('requirement_code',$r->code)->where('status','VERIFIED')->exists())throw ValidationException::withMessages(['documents'=>__('wave3.document_missing',['code'=>$r->code])]);$flags=$p->disclosureResponse?->referral_flags??[];$case=UnderwritingCase::create(['tenant_id'=>$p->tenant_id,'proposal_id'=>$p->id,'carrier_id'=>$p->offer->carrier_id,'status'=>'QUEUED','priority'=>$flags?'HIGH':'NORMAL','referral_reasons'=>$flags,'decision_due_at'=>now()->addWeekdays(2)]);foreach($flags as$f)UnderwritingReferralTask::create(['underwriting_case_id'=>$case->id,'reason_code'=>$f,'severity'=>'HIGH','due_at'=>$case->decision_due_at]);/* Straight-through processing: a proposal with no referral flags needs no human underwriter, so it goes directly to PAYMENT_PENDING; only flagged proposals wait in UNDER_REVIEW. */$straight=$flags===[];$to=$straight?'PAYMENT_PENDING':'UNDER_REVIEW';if($straight){\App\Models\UnderwritingDecision::create(['underwriting_case_id'=>$case->id,'decision'=>'APPROVED','reason_code'=>'STRAIGHT_THROUGH','notes'=>'Automatically approved: no disclosure raised a referral flag.','conditions'=>[],'decided_by'=>$actor->id,'decided_at'=>now()]);$case->update(['status'=>'DECIDED']);}$p->update(['status'=>$to,'submitted_at'=>now(),'decided_at'=>$straight?now():null,'version'=>$p->version+1]);$this->history($p,'DOCUMENTS_PENDING',$to,$straight?'STRAIGHT_THROUGH':'SUBMITTED',$actor,['underwriting_case_id'=>$case->id]);$this->audit->record('proposal.submitted','proposal',$p->id,['underwriting_case_id'=>$case->id]);$this->outbox->record('proposal.submitted','proposal',$p->id,['proposal_id'=>$p->id,'underwriting_case_id'=>$case->id]);return$p->refresh();});}private function history(Proposal$p,?string$from,string$to,string$reason,?User$actor,array$metadata=[]):void{DB::table('proposal_status_history')->insert(['id'=>(string)Str::uuid(),'proposal_id'=>$p->id,'from_status'=>$from,'to_status'=>$to,'reason_code'=>$reason,'actor_id'=>$actor?->id,'metadata'=>json_encode($metadata),'occurred_at'=>now()]);}}
